    int total = 0;
    std::function<void(int)> handler = [&total](int x) { total += x; };
    if (handler) {
        handler(7);
    }
    handler = {};
    if (handler) {
        handler(100);
    }
    std::cout << "total " << total << '\n';
}

#include <iostream>
#include <queue>
#include <functional>
#include <vector>
int main() {
    int n;
    if (!(std::cin >> n) || n < 0 || n > 12) {
        std::cout << "invalid\n";
        return 0;
    }
    std::vector<int> input(n);
    for (int &x : input) {
        if (!(std::cin >> x) || x < 0 || x > 9) {
            std::cout << "invalid\n";
            return 0;
        }
    }
    std::cin >> std::ws;
    if (!std::cin.eof()) {
        std::cout << "invalid\n";
        return 0;
    }
    std::queue<int> q;
    for (int x : input) {
        q.push(x);
    }
    int total = 0, processed = 0;
    std::function<void(int)> handler = [&](int x) {
        total += x;
        if (x == 3) {
            q.push(1);
        }
    };
    while (!q.empty()) {
        int event = q.front();
        q.pop();
        std::cout << "event " << event << '\n';
        if (handler) {
            handler(event);
        }
        ++processed;
    }
    std::cout << "total " << total << " processed " << processed << '\n';
}

